contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterC = address(c).balance;
        uint balAfterThis = address(this).balance;

        assert(!reverted || balBeforeC == 0 || balAfterC + amount == balBeforeC || balAfterThis + amount == balBeforeThis);
    }

    receive() external payable {}
}

